<?php
namespace App\Models;
use Illuminate\Database\Eloquent\Model;use Illuminate\Database\Eloquent\Relations\BelongsTo;use Illuminate\Database\Eloquent\Relations\HasMany;
/** Provides partner account behavior within the WorkIntel application. */ class PartnerAccount extends Model{protected $fillable=['uuid','owner_user_id','billing_workspace_id','name','slug','type','status','branding','commission_rate'];/** Defines attribute casting rules for the model. */ protected function casts():array{return ['branding'=>'array','commission_rate'=>'decimal:4'];}/** Handles the owner operation for the current WorkIntel workflow. */ public function owner():BelongsTo{return $this->belongsTo(User::class,'owner_user_id');}/** Handles the billing workspace operation for the current WorkIntel workflow. */ public function billingWorkspace():BelongsTo{return $this->belongsTo(Workspace::class,'billing_workspace_id');}/** Handles the members operation for the current WorkIntel workflow. */ public function members():HasMany{return $this->hasMany(PartnerAccountMember::class);}/** Handles the workspaces operation for the current WorkIntel workflow. */ public function workspaces():HasMany{return $this->hasMany(PartnerWorkspace::class);}/** Handles the api keys operation for the current WorkIntel workflow. */ public function apiKeys():HasMany{return $this->hasMany(PartnerApiKey::class);}}
